                StaticRecordListIndexEvent.dayPicked,
                metadata: EventMetadata(
                    data: payloadJSON(.integer("year", year), .integer("month", month), .integer("dayOfMonth", dayOfMonth)),
                    eventType: .externalEvent,
                    typedPayload: StaticRecordListIndexDayPickedPayload(year: year, month: month, dayOfMonth: dayOfMonth)
